// Unified component mapping role → icon
interface RoleIconProps {
  role: Role;
  size?: number;
  color?: string;
}

export function RoleIcon({ role, size = 24, color = '#E8D5FF' }: RoleIconProps) {
  switch (role) {
    case 'wolf':
      return <WolfIcon size={size} color={color} />;
    case 'villager':
      return <VillagerIcon size={size} color={color} />;
    case 'hunter':
      return <HunterIcon size={size} color={color} />;
    case 'oracle':
      return <OracleIcon size={size} color={color} />;
  }
}
